float gm_predict_delta(const float z[GM_N_FEATURES])
{
    float sum = GM_BIAS;
    for (uint32_t t = 0; t < GM_N_TREES; ++t) {
        const uint32_t start = gm_tree_start[t];
        uint32_t i = start;
        for (;;) {
            const gm_node_t *n = &gm_nodes[i];
            if (n->feat < 0) { sum += n->thr; break; }
            const float v = z[n->feat];
            const int go_left = isnan(v) ? n->dleft : (v <= n->thr);
            i = start + (uint32_t)(go_left ? n->left : n->right);
        }
    }
    return sum;
}

float gm_predict_glucose(const float z[GM_N_FEATURES], float baseline)
{
    float g = baseline + gm_predict_delta(z);
    if (g < GM_GLU_MIN) g = GM_GLU_MIN;
    if (g > GM_GLU_MAX) g = GM_GLU_MAX;
    return g;
}

gm_state_t gm_classify(float glucose_mg_dl)
{
    if (glucose_mg_dl <  GM_RULE_LO) return GM_LOW;
    if (glucose_mg_dl >  GM_RULE_HI) return GM_HIGH;
    return GM_NORMAL;
}

const char *gm_state_name(gm_state_t s)
{
    switch (s) { case GM_LOW: return "low"; case GM_HIGH: return "high"; default: return "normal"; }
}

/* ---------------- per-subject calibration (Welford, single pass) ---------------- */
void gm_calib_init(gm_calib_t *c)
{
    for (int i = 0; i < GM_N_FEATURES; ++i) { c->mean[i] = 0.0f; c->m2[i] = 0.0f; c->sd[i] = 1.0f; }
    c->baseline = 0.0f; c->glu_sum = 0.0f; c->n = 0; c->n_glu = 0; c->ready = 0;
}

void gm_calib_add(gm_calib_t *c, const float raw[GM_N_FEATURES])
{
    c->n++;
    for (int i = 0; i < GM_N_FEATURES; ++i) {
        const float d = raw[i] - c->mean[i];
        c->mean[i] += d / (float)c->n;
        c->m2[i]   += d * (raw[i] - c->mean[i]);
    }
}

void gm_calib_add_reference(gm_calib_t *c, float glucose_mg_dl)
{
    c->glu_sum += glucose_mg_dl; c->n_glu++;
}

int gm_calib_finish(gm_calib_t *c)
{
    if (c->n < 10 || c->n_glu < 1) return 0;          /* refuse to calibrate on too little */
    for (int i = 0; i < GM_N_FEATURES; ++i) {
        float var = c->m2[i] / (float)(c->n - 1);
        float sd  = (var > 0.0f) ? sqrtf(var) : 0.0f;
        c->sd[i]  = (sd > 1e-6f) ? sd : 1.0f;         /* matches the notebook: 0 sd -> 1.0 */
    }
    c->baseline = c->glu_sum / (float)c->n_glu;
    c->ready = 1;
    return 1;
}

void gm_apply_calib(const gm_calib_t *c, const float raw[GM_N_FEATURES], float z[GM_N_FEATURES])
{
    for (int i = 0; i < GM_N_FEATURES; ++i) {
        float v = (raw[i] - c->mean[i]) / c->sd[i];
        if (isnan(v) || isinf(v)) v = 0.0f;           /* matches the notebook's fillna(0) */
        z[i] = v;
    }
}
